// Physician Assistant - Medical Case Challenge Practice Test 5. Original questions written for Valus from the
// HOSA 2026–27 test plan, slightly harder than the sample items: short clinical cases across body systems,
// assessment and diagnostic reasoning not covered in Practice Tests 1–4.
import {q, mix} from './q.js';
const CMDT='Papadakis et al., Current Medical Diagnosis & Treatment', MP='MedlinePlus';
const DP='Disease Process & Terminology (includes cancer & neoplasms)', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders', ASSESS='Patient Assessment', DX='Diagnosis';

export default {
 id:'physician-assistant-5',
 event:'Physician Assistant - Medical Case Challenge',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Current Medical Diagnosis & Treatment (CMDT) and MedlinePlus',
 plan:[{area:DP,weight:10},{area:INTEG,weight:4},{area:MSK,weight:6},{area:CIRC,weight:10},{area:RESP,weight:6},{area:DIG,weight:10},{area:ENDO,weight:6},{area:NERV,weight:8},{area:REPRO,weight:4},{area:URIN,weight:4},{area:MENT,weight:6},{area:ASSESS,weight:12},{area:DX,weight:14}],
 questions:mix([
  q(DP,'A patient with long-standing high blood pressure has a thickened left ventricle made of larger, not more, muscle cells. What is this change called?','Hypertrophy',['Hyperplasia','Atrophy','Metaplasia, where one cell type is replaced by another'],'A','Hypertrophy is an increase in cell size, while hyperplasia is an increase in cell number.',CMDT),
  q(DP,'What does the prevalence of a disease measure?','The total number of existing cases in a population at a given time',['Only new cases over a period','The number of deaths from the disease','How fast the disease spreads from person to person'],'B','Prevalence counts all current cases, while incidence counts only new cases over a set time.',CMDT),
  q(DP,'A patient’s lymphoma shows no detectable signs after treatment. What term describes this?','Remission',['Relapse','Exacerbation','Metastasis'],'C','Remission may be partial or complete, and a return of disease afterward is called a relapse.',CMDT),
  q(DP,'What does the term “etiology” refer to?','The cause or origin of a disease',['The expected outcome','The treatment plan','The number of people affected'],'D','Knowing the etiology, such as a virus or a genetic change, guides treatment and prevention.',CMDT),
  q(DP,'A patient with diabetes also has high blood pressure and kidney disease. What are these additional conditions called?','Comorbidities',['Complications only','Sequelae of trauma','Prodromes'],'A','Comorbidities are other conditions present at the same time that can affect treatment and outcomes.',CMDT),
  q(INTEG,'A 4-year-old with asthma has dry, itchy, red patches in the creases of the elbows and knees. What is the likely diagnosis?','Atopic dermatitis (eczema)',['Psoriasis','Impetigo','Tinea corporis, a ring-shaped fungal rash'],'B','Atopic dermatitis is often linked with asthma and allergies, and moisturizers are a key part of care.',MP),
  q(INTEG,'An older adult has several waxy, brown lesions that look “stuck on” the skin of the back. What are they most likely?','Seborrheic keratoses',['Melanomas','Basal cell carcinomas','Actinic keratoses, which are rough, scaly precancers'],'C','Seborrheic keratoses are common, harmless growths that do not need treatment unless irritated.',MP),
  q(MSK,'A runner has sharp heel pain with the first steps in the morning that eases after walking. What is the likely diagnosis?','Plantar fasciitis',['Achilles tendon rupture','Gout','A stress fracture of the tibia'],'D','Stretching, supportive shoes and rest usually help this common overuse problem.',MP),
  q(MSK,'A new mother has pain at the base of the thumb when she bends her thumb into her fist and tilts her wrist toward the little finger. What is likely?','De Quervain tenosynovitis',['Carpal tunnel syndrome','Trigger finger','Scaphoid fracture'],'A','This positive Finkelstein test points to inflamed tendons along the thumb side of the wrist.',MP),
  q(MSK,'A tennis player has pain on the outside of the elbow that worsens when gripping. What is the likely diagnosis?','Lateral epicondylitis',['Medial epicondylitis','Olecranon bursitis','Ulnar nerve entrapment at the elbow'],'B','Lateral epicondylitis, or tennis elbow, is an overuse injury of the wrist extensor tendons.',MP),
  q(CIRC,'An ECG shows P waves and QRS complexes that occur at regular rates but have no relationship to each other. What is this?','Third-degree (complete) heart block',['First-degree heart block','Atrial fibrillation','Sinus tachycardia'],'C','The atria and ventricles beat independently, and a pacemaker is usually needed.',CMDT),
  q(CIRC,'A patient with a past heart attack has a fast, regular, wide-QRS rhythm and feels faint. What is the likely rhythm?','Ventricular tachycardia',['Sinus bradycardia','Atrial flutter with normal QRS','First-degree heart block'],'D','Ventricular tachycardia can quickly lead to cardiac arrest and needs urgent treatment.',CMDT),
  q(CIRC,'A child has petechiae and easy bruising a few weeks after a viral illness. The platelet count is very low, but other counts are normal. What is likely?','Immune thrombocytopenia (ITP)',['Iron deficiency anemia','Hemophilia A','Leukemia with very high white cells'],'A','In ITP the immune system destroys platelets, and many children recover on their own.',CMDT),
  q(CIRC,'A young athlete faints during exercise and has a murmur that gets louder with standing. What condition is a concern?','Hypertrophic cardiomyopathy',['Mitral valve prolapse only','Innocent flow murmur','Pericarditis'],'B','Hypertrophic cardiomyopathy is a leading cause of sudden cardiac death in young athletes.',CMDT),
  q(CIRC,'A patient has itching after warm showers, a red face and a very high hemoglobin. What is likely?','Polycythemia vera',['Iron deficiency anemia','Thalassemia','Sickle cell disease'],'C','Polycythemia vera is a bone marrow disorder that raises red cell mass and clot risk.',CMDT),
  q(RESP,'A smoker has shoulder pain, a drooping eyelid and a small pupil on the same side. What is suspected?','A Pancoast tumor at the lung apex causing Horner syndrome',['Asthma','Pneumonia','A rotator cuff tear from years of heavy lifting at work'],'D','Tumors at the top of the lung can press on nerves that control the eye and face.',CMDT),
  q(RESP,'An overweight patient snores loudly, stops breathing during sleep and is very sleepy during the day. What is likely?','Obstructive sleep apnea',['Narcolepsy','Asthma','Central sleep apnea caused by heart failure'],'A','A sleep study confirms the diagnosis, and CPAP is the main treatment.',CMDT),
  q(RESP,'A 6-month-old has a runny nose, then wheezing, fast breathing and feeding trouble in winter. What is the likely diagnosis?','Bronchiolitis, often caused by RSV',['Croup','Epiglottitis','Cystic fibrosis, which causes salty sweat and poor growth'],'B','Care is mainly supportive, with fluids, suctioning and oxygen if needed.',MP),
  q(DIG,'A young adult has belly pain relieved by bowel movements, with alternating diarrhea and constipation, and normal tests. What is likely?','Irritable bowel syndrome',['Crohn disease','Diverticulitis','Colon cancer that has spread to the liver'],'C','IBS is diagnosed by symptom patterns after warning signs such as bleeding and weight loss are ruled out.',MP),
  q(DIG,'A newborn has not passed meconium in 48 hours and has a swollen abdomen. A biopsy shows no nerve cells in part of the colon. What is this?','Hirschsprung disease',['Pyloric stenosis','Intussusception','Celiac disease'],'D','Without nerve cells, the bowel cannot push stool forward, and surgery removes the affected section.',MP),
  q(DIG,'A patient has right upper quadrant pain, fever and jaundice. Which condition does this triad suggest?','Ascending cholangitis',['Simple gallstones without infection','Hepatitis A','Peptic ulcer'],'A','Charcot triad points to infection of the bile ducts, which needs urgent antibiotics and drainage.',CMDT),
  q(DIG,'A patient has painless, bright red blood on the toilet paper after bowel movements. What is the most common cause?','Hemorrhoids',['Stomach ulcer','Esophageal varices','Small bowel bleeding'],'B','Bright red blood usually comes from the lower bowel, but older adults may need a colonoscopy to rule out cancer.',MP),
  q(DIG,'A patient has bloating, gas and diarrhea after drinking milk, with no weight loss. What is likely?','Lactose intolerance',['Celiac disease','Ulcerative colitis','Pancreatic cancer'],'C','A lack of lactase means milk sugar is fermented by gut bacteria, causing gas and diarrhea.',MP),
  q(ENDO,'An adult has larger hands and feet, a widening jaw and spacing between the teeth. Which hormone excess is likely?','Growth hormone (acromegaly)',['Cortisol','Thyroid hormone','Excess thyroid hormone from an overactive thyroid'],'D','Acromegaly is usually caused by a pituitary tumor and is screened with an IGF-1 level.',CMDT),
  q(ENDO,'Which medicine is usually first-line for a newly diagnosed adult with type 2 diabetes and normal kidney function?','Metformin',['Insulin glargine only','Prednisone','Levothyroxine'],'A','Metformin lowers liver glucose output and does not usually cause low blood sugar on its own.',CMDT),
  q(ENDO,'A patient has high blood pressure, low potassium and a low renin level. Which condition is suspected?','Primary aldosteronism (Conn syndrome)',['Pheochromocytoma','Hypothyroidism','Addison disease from failure of the adrenal glands'],'B','Too much aldosterone makes the kidneys keep sodium and lose potassium.',CMDT),
  q(NERV,'A patient has brief, electric-shock pains in the cheek triggered by chewing or touching the face. What is likely?','Trigeminal neuralgia',['Bell palsy','Cluster headache','Temporal arteritis'],'C','Carbamazepine is commonly used, and the pain follows branches of the fifth cranial nerve.',CMDT),
  q(NERV,'An older adult has a hand tremor when holding a cup that improves after a small amount of alcohol. What is likely?','Essential tremor',['Parkinson disease','Cerebellar stroke','Multiple sclerosis'],'D','Essential tremor occurs with action, while Parkinson tremor typically occurs at rest.',CMDT),
  q(NERV,'After a blow to the side of the head, a patient is briefly knocked out, wakes and talks normally, then quickly declines. What is suspected?','Epidural hematoma',['Concussion only','Migraine','Subdural hematoma that develops over weeks'],'A','The “lucid interval” is classic for arterial bleeding between the skull and the dura.',CMDT),
  q(NERV,'An older adult has gradual loss of side vision without pain and raised eye pressure. What is likely?','Open-angle glaucoma',['Cataract','Macular degeneration','Retinal detachment'],'B','Glaucoma damages the optic nerve slowly, so regular eye exams help find it early.',MP),
  q(REPRO,'A 25-year-old man has a firm, painless lump on one testicle. What should be suspected?','Testicular cancer',['Epididymitis','Testicular torsion','A hydrocele that glows with a light'],'C','Testicular cancer is most common in young men and is often curable when found early.',MP),
  q(REPRO,'At 32 weeks of pregnancy, a patient has sudden painless, bright red vaginal bleeding. What is suspected?','Placenta previa',['Placental abruption','Preeclampsia','Normal labor'],'D','A vaginal exam is avoided until ultrasound rules out placenta previa, because it can cause heavy bleeding.',MP),
  q(URIN,'A 68-year-old smoker has painless visible blood in the urine. Which cancer must be ruled out?','Bladder cancer',['Testicular cancer','Kidney stones only','Prostatitis'],'A','Smoking is the biggest risk factor for bladder cancer, and cystoscopy is used to evaluate it.',CMDT),
  q(URIN,'A patient has a sudden, strong urge to urinate and leaks before reaching the bathroom. What type of incontinence is this?','Urge incontinence (overactive bladder)',['Stress incontinence','Functional incontinence','Overflow incontinence from a bladder that never fully empties'],'B','Bladder training and medicines that relax the bladder muscle can help urge incontinence.',MP),
  q(MENT,'A normal-weight teen has repeated episodes of binge eating followed by vomiting. What is the likely diagnosis?','Bulimia nervosa',['Anorexia nervosa','Binge-eating disorder without purging','Pica'],'C','Repeated vomiting can cause low potassium, tooth erosion and swollen salivary glands.',MP),
  q(MENT,'A patient who uses opioids daily has yawning, runny nose, dilated pupils and diarrhea after stopping. What is happening?','Opioid withdrawal',['Opioid overdose','Alcohol withdrawal','A panic attack'],'D','Withdrawal is very uncomfortable but rarely life-threatening, unlike overdose.',MP),
  q(MENT,'A 3-year-old has delayed speech, limited eye contact and repeats the same play movements over and over. What should be evaluated?','Autism spectrum disorder',['ADHD only','Normal development','Hearing loss alone'],'A','Early evaluation and therapy help, and hearing is also tested to rule out other causes.',MP),
  q(ASSESS,'A patient with pneumonia says “ee,” but it sounds like “ay” through the stethoscope over one area. What is this finding?','Egophony, suggesting consolidation',['A pleural friction rub','Normal vesicular breath sounds','A heart murmur'],'B','Solid lung tissue carries sound better, which changes the “ee” to an “ay” sound.',CMDT),
  q(ASSESS,'When a patient with a swollen abdomen rolls onto one side, the dull area to percussion moves. What does this suggest?','Ascites (shifting dullness)',['Gas in the bowel','An enlarged spleen','An enlarged liver that moves when the patient changes position'],'C','Free fluid moves to the lowest point, which shifts the area that sounds dull.',CMDT),
  q(ASSESS,'Lifting a patient’s straight leg causes shooting pain below the knee. What does a positive straight-leg raise suggest?','A lumbar disc herniation pressing on a nerve root',['A hip fracture','Knee arthritis','A deep vein thrombosis in the calf that blocks blood flow to the foot'],'D','Pain radiating below the knee between 30 and 70 degrees suggests sciatica from a disc.',CMDT),
  q(ASSESS,'Before drawing an arterial blood gas from the wrist, why is an Allen test done?','To check that the ulnar artery can supply the hand',['To measure blood pressure','To find the radial vein','To test for carpal tunnel syndrome'],'A','If the radial artery is damaged, the ulnar artery must keep the hand supplied with blood.',CMDT),
  q(ASSESS,'In the Weber test, the sound is heard louder in the left ear. What does this suggest if hearing is reduced in the left ear?','Conductive hearing loss in the left ear',['Sensorineural loss in the left ear','Normal hearing','Sensorineural loss in both ears'],'B','In conductive loss, sound lateralizes to the affected ear; in sensorineural loss, it goes to the better ear.',CMDT),
  q(ASSESS,'What pulse oximetry reading is normal for a healthy adult at sea level?','95 to 100 percent',['70 to 80 percent','85 to 90 percent','100 to 110 percent'],'C','Readings below about 92 percent may need further evaluation and oxygen therapy.',MP),
  q(DX,'Which imaging test is commonly used to confirm a suspected kidney stone in an adult?','Noncontrast CT of the abdomen and pelvis',['Chest X-ray','Echocardiogram','An abdominal X-ray, which shows every type of stone clearly'],'D','Noncontrast CT shows the size and location of most stones, and ultrasound is used in pregnancy.',CMDT),
  q(DX,'A patient with rheumatoid arthritis has mild anemia with low serum iron, low TIBC and a normal or high ferritin. What is likely?','Anemia of chronic disease',['Iron deficiency anemia','Vitamin B12 deficiency','Sickle cell anemia'],'A','Inflammation traps iron in storage, so ferritin stays normal or high, unlike iron deficiency.',CMDT),
  q(DX,'A woman of childbearing age has lower abdominal pain. Which test should be done before ordering a CT scan?','A pregnancy (hCG) test',['A lipid panel','A thyroid test','A vitamin D level'],'B','A pregnancy test guides diagnosis, such as ectopic pregnancy, and protects a fetus from unneeded radiation.',CMDT),
  q(DX,'A Gram stain of pus from an abscess shows Gram-positive cocci in clusters. Which organism is most likely?','Staphylococcus aureus',['Streptococcus pyogenes','Escherichia coli','Neisseria gonorrhoeae'],'C','Staphylococci form grape-like clusters, while streptococci form chains.',CMDT),
  q(DX,'A drug lowers the risk of a stroke from 4% to 2% over 5 years. What is the number needed to treat (NNT)?','50',['2','25','100'],'D','The absolute risk reduction is 2%, and NNT = 1 ÷ 0.02 = 50 patients treated to prevent one stroke.',CMDT),
  q(DX,'A patient’s liver tests show AST more than twice as high as ALT. Which cause is most suggested?','Alcohol-related liver disease',['Acute viral hepatitis','Gallstones','Normal liver function'],'A','In viral hepatitis ALT is usually higher than AST, while alcohol often gives an AST:ALT ratio above 2.',CMDT),
  q(DX,'A health care worker needs testing for latent tuberculosis. Which blood test can be used instead of a skin test?','An interferon-gamma release assay (IGRA)',['A complete blood count','A sputum culture only','A chest X-ray, which is the only test for latent infection'],'B','IGRAs need only one visit and are not affected by prior BCG vaccination.',CMDT)
 ],9531)
};
